def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    blockers = set()
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0 and (r, c) not in seen:
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    x, y = stack.pop()
                    cells.append((x, y))
                    for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                        if (0 <= nx < h and 0 <= ny < w and (nx,ny) not in seen and grid[nx][ny] == v):
                            seen.add((nx,ny))
                            stack.append((nx,ny))
                objects.append((v, cells))
    # Objects furthest to the right settle first; each slides right until blocked.
    objects.sort(key=lambda obj: max(c for r, c in obj[1]), reverse=True)
    placed = set()
    result = [[0] * w for _ in range(h)]
    for v, cells in objects:
        # Original position is cleared from the working occupancy before sliding.
        for p in cells:
            placed.discard(p)
        shift = 0
        while True:
            nxt = [(r, c + shift + 1) for r, c in cells]
            if any(c >= w or (r, c) in placed for r, c in nxt):
                break
            shift += 1
        moved = [(r, c + shift) for r, c in cells]
        for p in moved:
            placed.add(p)
            result[p[0]][p[1]] = v
    return result
